#!/usr/bin/env python3
"""Pack props/ai-audio-new/bgm2_*.mp3 into props/bgm2-data.js.

The bgm2 series (#24-38 follow-up): one-track-per-scene new BGM generated
from docs/bgm-prompts.md. Kept in a separate directory + data file so the
new tracks never mix with the old ai-audio set. Missing files are skipped
silently — the engine falls back to synth beds until they exist."""
import base64
from pathlib import Path

HERE = Path(__file__).resolve().parent

out = [
    "// Generated by ai-audio-new/make-bgm2-data.py — do not edit.",
    "// bgm2 series: one-track-per-scene new BGM (docs/bgm-prompts.md).",
    "// Own global (VN_BGM2_ASSETS) so the series stays separate from the old",
    "// ai-audio set; audio.js merges it into the sampled-bed lookup.",
    "window.VN_BGM2_ASSETS = {",
]
total = 0
packed = 0
for f in sorted(HERE.glob("bgm2_*.mp3")):
    key = f.stem
    data = base64.b64encode(f.read_bytes()).decode()
    total += len(data)
    packed += 1
    out.append(f"  {key}: 'data:audio/mpeg;base64,{data}',")
out.append("};")
(HERE.parent / "bgm2-data.js").write_text("\n".join(out), encoding="utf-8")
print(f"bgm2-data.js written: {packed} tracks, base64 payload ~{total // 1024} KB")
